rules.logic:
// Collect all serp-item li elements that are organic results
const items = Array.from(element.querySelectorAll('li.serp-item'));
if (items.length === 0) return;

// A helper: returns true if the title is primarily English (Latin-script, no Cyrillic)
function isEnglishTitle(li) {
  const titleEl = li.querySelector('.OrganicTitleContentSpan, .OrganicTitle-LinkText');
  if (!titleEl) return false;
  const text = titleEl.textContent.trim();
  if (!text) return false;
  // Count Cyrillic characters
  const cyrillicCount = (text.match(/[\u0400-\u04FF]/g) || []).length;
  // Count Latin letters
  const latinCount = (text.match(/[A-Za-z]/g) || []).length;
  // Treat as English if there are Latin chars and virtually no Cyrillic
  // (allow a few Cyrillic chars for mixed titles like "CATS — ВКонтакте" → has Cyrillic → Russian)
  return latinCount > 0 && cyrillicCount === 0;
}

const russianItems = [];
const englishItems = [];

for (const li of items) {
  if (isEnglishTitle(li)) {
    englishItems.push(li);
  } else {
    russianItems.push(li);
  }
}

// Move all English items to the end (after all Russian items)
// appendChild is idempotent: re-running produces same result
for (const li of englishItems) {
  element.appendChild(li);
}
